import 'package:flutter/material.dart';
import 'package:supabase_flutter/supabase_flutter.dart';

class EmployeeApprovalsScreen extends StatefulWidget { const EmployeeApprovalsScreen({super.key}); @override State<EmployeeApprovalsScreen> createState()=>_EmployeeApprovalsScreenState(); }
class _EmployeeApprovalsScreenState extends State<EmployeeApprovalsScreen>{final _client=Supabase.instance.client;bool _loading=true;String? _error;List<Map<String,dynamic>> _rows=[];
 @override void initState(){super.initState();_load();}
 Future<void> _load()async{setState(()=>_loading=true);try{final data=await _client.from('employee_approval_requests').select('id,employee_id,request_payload,created_at,users!employee_approval_requests_employee_id_fkey(id,agent_code,name,phone,role,team_id)').eq('status','PENDING').order('created_at');setState(()=>_rows=data.map((e)=>Map<String,dynamic>.from(e)).toList());}catch(e){setState(()=>_error=e.toString());}finally{if(mounted)setState(()=>_loading=false);}}
 Future<void> _review(Map<String,dynamic> row,bool approve)async{final reason=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(ctx)=>AlertDialog(title:Text(approve?'Approve employee':'Reject employee'),content:TextField(controller:reason,decoration:const InputDecoration(labelText:'Decision note (required)'),minLines:2,maxLines:4),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:Text(approve?'Approve':'Reject'))]));if(ok!=true||reason.text.trim().length<3)return;try{final id=row['employee_id'].toString();await _client.from('employee_approval_requests').update({'status':approve?'APPROVED':'REJECTED','reviewed_by':_client.auth.currentUser?.id,'review_reason':reason.text.trim(),'reviewed_at':DateTime.now().toUtc().toIso8601String()}).eq('id',row['id']);await _client.from('users').update({'id_approval_status':approve?'APPROVED':'REJECTED','status':approve?'active':'inactive'}).eq('id',id);if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(approve?'Employee approved.':'Employee rejected.')));await _load();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Review failed: $e')));}}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Employee Approvals'),actions:[IconButton(onPressed:_load,icon:const Icon(Icons.refresh))]),body:_loading?const Center(child:CircularProgressIndicator()):_error!=null?Center(child:Padding(padding:const EdgeInsets.all(24),child:Text('Approval queue unavailable: $_error'))):_rows.isEmpty?const Center(child:Text('No pending employee approvals.')):ListView.separated(padding:const EdgeInsets.all(16),itemCount:_rows.length,separatorBuilder:(_,__)=>const SizedBox(height:8),itemBuilder:(ctx,i){final row=_rows[i];final employee=row['users'] is Map?Map<String,dynamic>.from(row['users'] as Map):<String,dynamic>{};final payload=row['request_payload'] is Map?Map<String,dynamic>.from(row['request_payload'] as Map):<String,dynamic>{};return Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text((employee['name']??'Unknown employee').toString(),style:Theme.of(context).textTheme.titleMedium),Text('Code: ${employee['agent_code']??payload['employee_code']??'—'}'),Text('Phone: ${employee['phone']??'—'}'),Text('Requested role: ${payload['role']??employee['role']??'—'}'),Text('Submitted: ${row['created_at']??'—'}'),const SizedBox(height:10),Row(children:[Expanded(child:OutlinedButton(onPressed:()=>_review(row,false),child:const Text('Reject'))),const SizedBox(width:8),Expanded(child:FilledButton(onPressed:()=>_review(row,true),child:const Text('Approve')))])]))); }));
}
